import { MeshBasicNodeMaterial } from 'three/webgpu';
import { Group, Mesh, PlaneGeometry } from '@/primitives';

export default function createNode(config, ctx) {
  // root container
  const root = new Group();

  // geometry preserving image aspect (512 : 320 = 1.6)
  const aspect = 512 / 320;
  const width = 1.6; // arbitrary unit, matches aspect
  const height = 1;
  const geometry = new PlaneGeometry(width, height);

  // material – will receive texture later
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    map: null,
    transparent: true,
  });

  const plane = new Mesh(geometry, material);
  // apply placement from spec (already handled by adapter for root, but keep for safety)
  plane.position.set(3.2, 1, 0.06);
  plane.rotation.set(0, 0, 0);
  plane.scale.set(1, 1, 1);
  root.add(plane);

  // load texture asynchronously; keep reference for cleanup
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // render text items via font atlas
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: (config.visualSpec?.colors?.paper ?? '#e8ecf2') as any,
      align: 'center',
    });
    // place text slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // no primitives to apply per spec

  // cleanup routine
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (loadedTexture) {
      loadedTexture.dispose();
    }
    // No GSAP timelines were created, but ensure any could be killed
    // if (root.userData._timelines) root.userData._timelines.forEach(t => t.kill());
  };

  // placeholder for handlers object (no interactions in spec)
  root.userData.handlers = {};

  return root;
}
